import{_ as n,o as s,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"43. Reading and Writing Binary Files","description":"The Little Book of C — 43. Reading and Writing Binary Files","frontmatter":{"title":"43. Reading and Writing Binary Files","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Input Output and Files"],"description":"The Little Book of C — 43. Reading and Writing Binary Files","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":43,"sidebarWeight":43,"lang":"en-US","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/043-Reading and Writing Binary Files","alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/043-Reading and Writing Binary Files"},"headers":[],"relativePath":"posts/c教程/en-US/05-Input Output and Files/043-Reading and Writing Binary Files.md","filePath":"posts/c教程/en-US/05-Input Output and Files/043-Reading and Writing Binary Files.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/05-Input Output and Files/043-Reading and Writing Binary Files.md"};function p(o,a,l,r,d,c){return s(),e("div",null,[...a[0]||(a[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/05-输入输出与文件/043-Reading and Writing Binary Files)</p><p>Text files are easy to read but not always efficient. Binary files, on the other hand, store raw bytes exactly as they exist in memory, no formatting, no conversions. They’re ideal for saving arrays, structs, or any data that must be written and read back quickly without loss or rounding.</p><h4 id="text-vs-binary" tabindex="-1">Text vs Binary <a class="header-anchor" href="#text-vs-binary" aria-label="Permalink to &quot;Text vs Binary&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Aspect</th><th>Text File</th><th>Binary File</th></tr></thead><tbody><tr><td>Format</td><td>Human-readable (ASCII)</td><td>Raw bytes</td></tr><tr><td>Size</td><td>Larger (extra characters, newlines)</td><td>Smaller (compact form)</td></tr><tr><td>Read/Write</td><td><code>fprintf</code>,<code>fscanf</code>,<code>fgets</code></td><td><code>fwrite</code>,<code>fread</code></td></tr><tr><td>Use Case</td><td>Logs, config, reports</td><td>Structs, images, executables, serialized data</td></tr></tbody></table><p>When you open a file for binary I/O, add<code>b</code> to the mode:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *fp = fopen(&quot;data.bin&quot;, &quot;wb&quot;); // write binary</span></span>
<span class="line"><span>FILE *fp = fopen(&quot;data.bin&quot;, &quot;rb&quot;); // read binary</span></span></code></pre></div><h4 id="writing-binary-data" tabindex="-1">Writing Binary Data <a class="header-anchor" href="#writing-binary-data" aria-label="Permalink to &quot;Writing Binary Data&quot;">​</a></h4><p>Let’s write an array of integers directly to disk.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int numbers[] = {10, 20, 30, 40, 50};</span></span>
<span class="line"><span>    size_t count = sizeof(numbers) / sizeof(numbers[0]);</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;numbers.bin&quot;, &quot;wb&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Failed to open file&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    fwrite(numbers, sizeof(int), count, fp);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    printf(&quot;Wrote %zu integers to numbers.bin\\n&quot;, count);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This writes 5 integers (4 bytes each on most systems) directly to disk as raw bytes, no text conversion.</p><h4 id="reading-binary-data" tabindex="-1">Reading Binary Data <a class="header-anchor" href="#reading-binary-data" aria-label="Permalink to &quot;Reading Binary Data&quot;">​</a></h4><p>Now let’s read them back:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int numbers[5];</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;numbers.bin&quot;, &quot;rb&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Failed to open file&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    size_t n = fread(numbers, sizeof(int), 5, fp);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    printf(&quot;Read %zu integers:\\n&quot;, n);</span></span>
<span class="line"><span>    for (size_t i = 0; i &lt; n; i++)</span></span>
<span class="line"><span>        printf(&quot;%d &quot;, numbers[i]);</span></span>
<span class="line"><span>    printf(&quot;\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Wrote 5 integers to numbers.bin</span></span>
<span class="line"><span>Read 5 integers:</span></span>
<span class="line"><span>10 20 30 40 50</span></span></code></pre></div><h4 id="writing-and-reading-structs" tabindex="-1">Writing and Reading Structs <a class="header-anchor" href="#writing-and-reading-structs" aria-label="Permalink to &quot;Writing and Reading Structs&quot;">​</a></h4><p>You can store whole structures directly using the same pattern.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>typedef struct {</span></span>
<span class="line"><span>    int id;</span></span>
<span class="line"><span>    float price;</span></span>
<span class="line"><span>    char title[50];</span></span>
<span class="line"><span>} Book;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    Book b1 = {1, 9.99, &quot;The C Book&quot;};</span></span>
<span class="line"><span>    Book b2 = {2, 15.49, &quot;Algorithms in C&quot;};</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;books.bin&quot;, &quot;wb&quot;);</span></span>
<span class="line"><span>    if (!fp) return 1;</span></span>
<span class="line"><span>    fwrite(&amp;b1, sizeof(Book), 1, fp);</span></span>
<span class="line"><span>    fwrite(&amp;b2, sizeof(Book), 1, fp);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    fp = fopen(&quot;books.bin&quot;, &quot;rb&quot;);</span></span>
<span class="line"><span>    if (!fp) return 1;</span></span>
<span class="line"><span>    Book b;</span></span>
<span class="line"><span>    while (fread(&amp;b, sizeof(Book), 1, fp) == 1)</span></span>
<span class="line"><span>        printf(&quot;%d | %s | %.2f\\n&quot;, b.id, b.title, b.price);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 | The C Book | 9.99</span></span>
<span class="line"><span>2 | Algorithms in C | 15.49</span></span></code></pre></div><h4 id="handling-endianness" tabindex="-1">Handling Endianness <a class="header-anchor" href="#handling-endianness" aria-label="Permalink to &quot;Handling Endianness&quot;">​</a></h4><p>Binary files depend on the CPU’s byte order (endianness). If you write on a little-endian machine and read on a big-endian one, bytes may appear reversed.</p><p>For portable formats, you can:</p><ul><li>Use standardized serialization (like Protocol Buffers or MessagePack).</li><li>Convert manually using bit shifts or network-byte-order functions (<code>htonl</code>,<code>ntohl</code>).</li></ul><p>Example for manual conversion:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unsigned int to_big_endian(unsigned int x) {</span></span>
<span class="line"><span>    return ((x &amp; 0xFF) &lt;&lt; 24) |</span></span>
<span class="line"><span>           ((x &amp; 0xFF00) &lt;&lt; 8) |</span></span>
<span class="line"><span>           ((x &amp; 0xFF0000) &gt;&gt; 8) |</span></span>
<span class="line"><span>           ((x &gt;&gt; 24) &amp; 0xFF);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="appending-binary-data" tabindex="-1">Appending Binary Data <a class="header-anchor" href="#appending-binary-data" aria-label="Permalink to &quot;Appending Binary Data&quot;">​</a></h4><p>You can append more records with mode<code>&quot;ab&quot;</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Book b3 = {3, 21.75, &quot;Advanced C&quot;};</span></span>
<span class="line"><span>FILE *fp = fopen(&quot;books.bin&quot;, &quot;ab&quot;);</span></span>
<span class="line"><span>fwrite(&amp;b3, sizeof(Book), 1, fp);</span></span>
<span class="line"><span>fclose(fp);</span></span></code></pre></div><h4 id="binary-file-utilities" tabindex="-1">Binary File Utilities <a class="header-anchor" href="#binary-file-utilities" aria-label="Permalink to &quot;Binary File Utilities&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Function</th><th>Purpose</th></tr></thead><tbody><tr><td><code>fwrite(ptr, size, count, file)</code></td><td>Write binary data</td></tr><tr><td><code>fread(ptr, size, count, file)</code></td><td>Read binary data</td></tr><tr><td><code>fseek(file, offset, origin)</code></td><td>Move position</td></tr><tr><td><code>ftell(file)</code></td><td>Get current position</td></tr><tr><td><code>rewind(file)</code></td><td>Go back to start</td></tr></tbody></table><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Binary I/O is essential for:</p><ul><li>Saving large datasets efficiently</li><li>Game save files, multimedia formats, or scientific data</li><li>Databases and memory-mapped storage</li><li>Embedded and system-level tools</li></ul><p>It’s the foundation of serialization, transforming data in memory into bytes that can travel or persist.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Save an array of<code>double</code> values and read them back.</li><li>Modify the struct example to include an<code>enum</code> field and test the binary result.</li><li>Implement a function<code>count_records(filename)</code> that counts how many structs are stored.</li><li>Use<code>fseek()</code> to jump to the third record and print only that one.</li><li>Write both text and binary versions of the same file and compare sizes.</li></ol><p>Binary I/O connects C’s low-level power to real-world storage efficiency. Next, you’ll expand this further by understanding standard streams, how to use<code>stdin</code>,<code>stdout</code>, and<code>stderr</code> to build flexible, composable command-line tools.</p>`,38)])])}const b=n(i,[["render",p]]);export{h as __pageData,b as default};
